/**
 * Synthetic media for the CCTV demo mocks.
 *
 * The public demo has no real recorder behind it, so the console's binary
 * endpoints (`/snapshot`, `/playback`, `/export`) are answered with these
 * generated stand-ins: four schematic surveillance stills — one per demo
 * channel — and one short clip whose burned-in timestamp advances so the
 * archive player visibly plays instead of looking frozen.
 *
 * Generated, not photographic, and deliberately so: the demo should read as a
 * product walkthrough, never as real footage from someone's premises.
 */

/** Decode a base64 payload into the raw bytes an HttpResponse can stream. */
export function base64ToBytes(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    // `atob` yields a binary string: every character is one byte, 0-255.
    // Decoding it needs code UNITS, so `charCodeAt` is the right primitive —
    // `codePointAt` reads Unicode code points, which is a different question
    // that only happens to have the same answer below 0x10000. NOSONAR S7758.
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

