/** JPEG bytes for a channel, falling back to channel 1 for unknown indexes. */
export function cctvFrameBytes(channel: number): Uint8Array {
  return base64ToBytes(FRAMES_BASE64[channel] ?? FRAMES_BASE64[1]!);
}

/** MP4 bytes for the archive clip. */
export function cctvClipBytes(): Uint8Array {
  return base64ToBytes(CLIP_BASE64);
}
